#!/bin/bash
# Auto-Fix PR Creation Script (KAN-307 3D)
# Creates a PR with auto-fix changes

set -euo pipefail

BRANCH_NAME="auto-fix/$(date +%Y%m%d-%H%M%S)"
PR_TITLE="chore: auto-fix formatting and style issues"
PR_BODY="This PR contains automated fixes for code style issues detected by the auto-fix engine.

## Changes
- Applied black formatting
- Applied isort import sorting
- Cleaned up trailing whitespace

## Testing
All existing tests pass.

---
*Auto-generated by KAN-307 AI Auto-Fix Engine*"

echo "Creating auto-fix branch: ${BRANCH_NAME}"
git checkout -b "${BRANCH_NAME}"

# Stage changes
git add -A

# Commit if there are changes
if ! git diff --cached --quiet; then
    git commit -m "${PR_TITLE}

${PR_BODY}"
    git push origin "${BRANCH_NAME}"

    # Create PR
    if [[ -n "${GITHUB_TOKEN:-}" && -n "${GITHUB_REPOSITORY:-}" ]]; then
        echo "Creating PR..."
        gh pr create \
            --title "${PR_TITLE}" \
            --body "${PR_BODY}" \
            --base main \
            --head "${BRANCH_NAME}" \
            --label "auto-fix,maintenance" || echo "Failed to create PR"
    fi
else
    echo "No changes to commit"
    git checkout main
    git branch -D "${BRANCH_NAME}"
fi